<script setup lang="ts">
/**
 * Plain text still arriving, with a steady caret (`design/components/streaming-text.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/streaming-text.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Text as TextVNode, isVNode } from 'vue'

import styles from '@polymorph/recipes/ai/streaming-text.module.css'
import Skeleton from '../structure/Skeleton.vue'

export type StreamingTextSize = NonNullable<StreamingTextProps['size']>

export interface StreamingTextProps {
  /**
   * The text step (Text's `sm` or `md`), for the same reason Text has two.
   */
  size?: 'sm' | 'md'
  /**
   * Whether more is coming, which shows the caret and sets `aria-busy` on the root.
   */
  streaming?: boolean
}

defineOptions({ name: 'StreamingText', inheritAttrs: false })

withDefaults(defineProps<StreamingTextProps>(), { size: 'md', streaming: false })
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
// The text the caller put in a slot: its text nodes, in order, without the elements'.
const slotText = (slot: ((...args: never[]) => unknown) | undefined): string => {
  const read = (nodes: unknown): string =>
    typeof nodes === 'string'
      ? nodes
      : Array.isArray(nodes)
        ? nodes.map(read).join('')
        : isVNode(nodes) && nodes.type === TextVNode
          ? read(nodes.children)
          : ''
  return read(slot?.())
}
</script>

<template>
  <div
    :class="styles.root"
    :data-size="size"
    :data-state="streaming ? 'streaming' : undefined"
    :data-pending="streaming && slotText($slots.default) === '' ? '' : undefined"
    :aria-busy="streaming ? true : undefined"
    data-member="streaming-text"
  >
    <Skeleton
      v-if="streaming && slotText($slots.default) === ''"
      shape="text"
      :textStep="size"
      :width="9"
    />
    <p v-else :class="styles.text">
      <slot />
      <span v-if="streaming" :class="styles.caret" aria-hidden="true" />
    </p>
  </div>
</template>
